solutionCode:
public class Solution {
    static class Builder {
        private char[] dados = new char[1];
        private int tamanho;
        private long copias;

        // O(1) amortizado: a cópia O(n) acontece só quando o array dobra.
        Builder append(char c) {
            if (tamanho == dados.length) {
                char[] maior = new char[dados.length * 2];
                System.arraycopy(dados, 0, maior, 0, tamanho);
                copias += tamanho;
                dados = maior;
            }
            dados[tamanho++] = c;
            return this;
        }

        Builder append(String s) {
            for (int i = 0; i < s.length(); i++) append(s.charAt(i));
            return this;
        }

        int length() { return tamanho; }
        long copias() { return copias; }

        @Override public String toString() { return new String(dados, 0, tamanho); }
    }
}

