import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void montaTexto() {
        var b = new Solution.Builder();
        b.append("ola").append(' ').append("mundo");
        assertEquals("ola mundo", b.toString());
        assertEquals(9, b.length());
    }

    @Test void copiasAbaixoDe2n() {
        var b = new Solution.Builder();
        int n = 1_000_000;
        for (int i = 0; i < n; i++) b.append('x');
        assertEquals(n, b.length());
        assertTrue(b.copias() < 2L * n, "cópias = " + b.copias());
        assertTrue(b.copias() > 0, "o array precisa ter crescido");
    }

    @Test void dobraACadaEnchimento() {
        var b = new Solution.Builder();
        for (int i = 0; i < 9; i++) b.append('a');
        // capacidades 1→2→4→8→16: cópias 1 + 2 + 4 + 8 = 15
        assertEquals(15, b.copias());
    }
}
